-- BEFORE UPDATE receives an unassigned NEW.ctid, not SQLite's stable rowid.
-- PostgreSQL never permits changing ctid directly. Preserve every logical key,
-- immutable audit fact, lease, owner, timestamp and dispatch transition guard.
-- Keep the applied baseline immutable and repair only the verified function.
CREATE OR REPLACE FUNCTION "fn_trg_assistant_audits_update_prd077"() RETURNS trigger
LANGUAGE plpgsql AS $trigger$
BEGIN
  IF (NEW.assistant_audit_id<>OLD.assistant_audit_id OR NEW.assistant_event_id<>OLD.assistant_event_id OR NEW.tenant_id<>OLD.tenant_id OR NEW.assistant_query_id<>OLD.assistant_query_id OR NEW.actor_user_id<>OLD.actor_user_id OR NEW.actor_session_id<>OLD.actor_session_id OR NEW.audit_log_id<>OLD.audit_log_id OR NEW.required_permissions_json<>OLD.required_permissions_json OR NEW.source_types_json<>OLD.source_types_json OR NEW.permission_revision<>OLD.permission_revision OR NEW.authorization_fingerprint<>OLD.authorization_fingerprint OR NEW.answer_schema_version<>OLD.answer_schema_version OR NEW.outcome<>OLD.outcome OR NEW.claim_count<>OLD.claim_count OR NEW.source_count<>OLD.source_count OR NEW.redaction_count<>OLD.redaction_count OR NEW.query_duration_ms<>OLD.query_duration_ms OR NEW.operation_request_id<>OLD.operation_request_id OR NEW.operation_trace_id<>OLD.operation_trace_id OR NEW.execution_mode<>OLD.execution_mode OR NEW.model_call_count<>OLD.model_call_count OR NEW.model_input_tokens<>OLD.model_input_tokens OR NEW.model_output_tokens<>OLD.model_output_tokens OR NEW.model_cost_cny_micros<>OLD.model_cost_cny_micros OR NEW.model_cost_status<>OLD.model_cost_status OR NEW.created_at<>OLD.created_at OR unixepoch(NEW.updated_at)<=unixepoch(OLD.updated_at) OR NOT( ( OLD.event_dispatch_status='pending' AND NEW.event_dispatch_status='processing' AND OLD.event_dispatch_attempts<10 AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1 AND unixepoch(OLD.event_next_attempt_at)<=unixepoch(NEW.updated_at) AND unixepoch(NEW.event_lease_expires_at)>unixepoch(NEW.updated_at) ) OR ( OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='processing' AND OLD.event_dispatch_attempts<10 AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts+1 AND NEW.event_claim_token<>OLD.event_claim_token AND unixepoch(OLD.event_lease_expires_at)<=unixepoch(NEW.updated_at) AND unixepoch(NEW.event_lease_expires_at)>unixepoch(NEW.updated_at) ) OR ( OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status='processing' AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts AND NEW.event_next_attempt_at IS NOT DISTINCT FROM OLD.event_next_attempt_at AND NEW.event_claim_token=OLD.event_claim_token AND NEW.event_lease_owner_id=OLD.event_lease_owner_id AND NEW.event_last_error_code IS NOT DISTINCT FROM OLD.event_last_error_code AND NEW.event_dispatched_at IS NOT DISTINCT FROM OLD.event_dispatched_at AND unixepoch(NEW.updated_at)>unixepoch(OLD.updated_at) AND unixepoch(OLD.event_lease_expires_at)>unixepoch(NEW.updated_at) AND unixepoch(NEW.event_lease_expires_at)>unixepoch(OLD.event_lease_expires_at) ) OR ( OLD.event_dispatch_status='processing' AND NEW.event_dispatch_status IN('pending','dispatched','failed') AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts AND unixepoch(OLD.event_lease_expires_at)>unixepoch(NEW.updated_at) ) OR ( OLD.event_dispatch_status='processing' AND OLD.event_dispatch_attempts=10 AND NEW.event_dispatch_status='failed' AND NEW.event_dispatch_attempts=OLD.event_dispatch_attempts AND unixepoch(OLD.event_lease_expires_at)<=unixepoch(NEW.updated_at) ) OR ( OLD.event_dispatch_status IN('pending','processing') AND NEW.event_dispatch_status='failed' AND NEW.event_dispatch_attempts=10 AND ( strftime('%Y-%m-%dT%H:%M:%SZ',OLD.updated_at) IS DISTINCT FROM OLD.updated_at OR ( OLD.event_next_attempt_at IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',OLD.event_next_attempt_at) IS DISTINCT FROM OLD.event_next_attempt_at ) OR ( OLD.event_lease_expires_at IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%SZ',OLD.event_lease_expires_at) IS DISTINCT FROM OLD.event_lease_expires_at ) ) ) )) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='assistant_audit_transition_invalid';
  END IF;
  RETURN NEW;
END;
$trigger$;
